from pathlib import Path
import json,subprocess,hashlib,csv,struct
import numpy as np
R=Path('/workspace/scratch/a9592b052b11/a27'); CAP=R/'capture'; RATE=48000
inventory=json.loads((R/'inventory.json').read_text()); ids=inventory['parameter_ids']; byname={p['name']:p for p in inventory['programs']}
requests=[]
for note in (36,60):
 for velocity in (.3,.85):requests.append(('Picked Bass',note,velocity,0,4,.5))
requests.extend([('Rubber Bass',48,.85,0,4,.5),('Sine Bass',48,.85,0,2,.3),('Sine Lead',67,.8,0,2,.3),('Trill Lead',67,.8,0,2,.3),('Pressure Lead',67,.8,0,2,.3),('Pressure Lead',67,.8,1,2,.3)])
commands=[]; results=[]
def wav(path):
 raw=path.read_bytes(); off=12; data=None
 while off+8<=len(raw):
  kind,size=struct.unpack_from('<4sI',raw,off);chunk=raw[off+8:off+8+size]
  if kind==b'data':data=chunk
  off+=8+size+(size&1)
 return np.frombuffer(data,dtype='<f4').reshape(-1,2).astype(np.float64)
def rms(a):return float(np.sqrt(np.mean(a*a)))
def db(a):return float(20*np.log10(max(a,1e-12)))
def hratio(a,start,end,f0):
 y=a[int(start*RATE):int(end*RATE)].mean(axis=1);n=len(y); y=(y-y.mean())*np.hanning(n); fft=np.abs(np.fft.rfft(y))**2;freq=np.fft.rfftfreq(n,1/RATE);width=max(3.,2.0*RATE/n)
 powers=[float(fft[np.abs(freq-f0*h)<width].sum()) for h in range(1,13)]
 return float(10*np.log10(max(sum(powers[1:]),1e-30)/max(powers[0],1e-30)))
def digest(values):
 h=14695981039346656037
 for v in values:
  for b in struct.pack('<f',v):h=((h^b)*1099511628211)&((1<<64)-1)
 return h
for i,(name,note,velocity,pressure,hold,tail) in enumerate(requests):
 out=R/f'clip-{i:02d}';cmd=[str(CAP),'--library','all','--out',str(out),'--wav','--preset',name,'--note',str(note),'--velocity',str(velocity),'--pressure',str(pressure),'--hold',str(hold),'--tail',str(tail),'--rate',str(RATE)]
 subprocess.run(cmd,check=True,stdout=subprocess.DEVNULL);commands.append(cmd)
 metric=next(csv.DictReader((out/'metrics.csv').open())); assert int(metric['parameter_digest'],16)==digest(byname[name]['values'])
 a=wav(next(out.glob('*.wav')));assert np.isfinite(a).all();assert np.abs(a).max()<=1
 p=dict(zip(ids,byname[name]['values'])); foot=[.5,1,1.5,2,3,4][int(p['ch1_feet'])];f0=440*2**((note-69)/12)*foot
 res={'program':name,'note':note,'velocity':velocity,'pressure':pressure,'hold':hold,'tail':tail,'frames':len(a),'peak_dbfs':db(float(np.abs(a).max())),'onset_dbfs':db(rms(a[int(.02*RATE):int(.08*RATE)])),'body_dbfs':db(rms(a[int(.8*RATE):int(1.1*RATE)])),'body_upper_to_fundamental_db':hratio(a,.5,1.5,f0),'nonfinite':0,'samples_over_full_scale':0,'wav_sha256':hashlib.sha256(next(out.glob('*.wav')).read_bytes()).hexdigest(),'parameter_digest':metric['parameter_digest']}
 if hold==4:res['late_relative_to_onset_db']=db(rms(a[int(3.5*RATE):int(3.9*RATE)]))-res['onset_dbfs']
 results.append(res)
summary={'conditions':len(results),'seconds':sum(x['hold']+x['tail'] for x in results),'samples':sum(x['frames']*2 for x in results),'peak_dbfs':max(x['peak_dbfs'] for x in results),'results':results,'commands':commands}
(R/'audio.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps(summary,indent=2))

