#include "core/Engine.h"
#include "core/FactoryPresets.h"
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdio>
#include <string>
#include <memory>
using namespace cs80;
int main(){
 for(const char* name:{"Glide Lead","Glissando Lead","Trill Lead"}){
  const auto& bank=programLibrary(); auto it=std::find_if(bank.begin(),bank.end(),[&](const auto& p){return p.name==name;}); if(it==bank.end())return 2;
  auto e=std::make_unique<Engine>();e->prepare(48000);e->setParams(it->values);std::array<float,512>b{};
  const bool trill=std::string(name)=="Trill Lead";e->noteOn(trill?67:60,.8f,1);
  for(int i=0;i<94;++i)e->render(b.data(),256);
  if(!trill){e->noteOff(60,1);e->noteOn(72,.8f,1);}
  for(int i=0;i<280;++i){e->render(b.data(),256);
   for(float s:b)if(!std::isfinite(s))return 3;
   for(int v=0;v<8;++v){auto info=e->getVoiceInfo(v);if(info.active&&info.held&&info.note==(trill?67:72)){
    double hz=e->getRankInfo(v,0).oscillatorHz;double pitch=69+12*std::log2(hz/440.);
    std::printf("%s,%.9f,%.9f\n",name,(i+1)*256./48000,pitch);break;}}
  }
 }
}
